const i=document.querySelectorAll(".reveal-item");if(i.length){const t=s=>{s.classList.add("is-visible")},r=new IntersectionObserver(s=>{s.forEach(e=>{e.isIntersecting&&(t(e.target),r.unobserve(e.target))})},{rootMargin:"0px 0px -5% 0px",threshold:0});i.forEach(s=>{s.classList.contains("is-visible")||r.observe(s)}),window.setTimeout(()=>{i.forEach(s=>{s.classList.contains("is-visible")||t(s)})},1800)}
